METHODS = ['_create_ribbon', '_create_fixed_tools_panel', '_create_sequence_panel', '_create_sequence_row', '_update_sequence_row', '_sequence_row_signature', '_update_sequence_row_selection', '_update_summary']


def fail(message: str) -> None:
    raise SystemExit(f"ERREUR : {message}\nAucun fichier n'a été modifié.")


def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def replace_method(source: str, name: str, new_block: str) -> str:
    lines = source.splitlines(keepends=True)
    start = None
    for index, line in enumerate(lines):
        if line.startswith(f"    def {name}("):
            start = index
            break
    if start is None:
        fail(f"méthode {name} introuvable")

    end = len(lines)
    for index in range(start + 1, len(lines)):
        line = lines[index]
        if line.startswith("    def ") or line.startswith("    @"):
            end = index
            break

    return (
        "".join(lines[:start])
        + new_block.rstrip()
        + "\n\n"
        + "".join(lines[end:])
    )


def main() -> None:
    if not TARGET.is_file():
        fail(f"fichier introuvable : {TARGET}")

    original = TARGET.read_text(encoding="utf-8")
    if MARKER in original:
        print("MAQUETTAGE_RAIL_CARTES_DEJA_APPLIQUE")
        return

    current_hash = sha256(TARGET)
    if current_hash != EXPECTED_SHA256:
        fail(
            "la version de mockup_view.py n'est pas exactement celle que vous "
            "venez de me transmettre. Par sécurité, la correction est refusée."
        )

    candidate = original
    for name in METHODS:
        candidate = replace_method(candidate, name, BLOCKS[name])

    try:
        compile(candidate, str(TARGET), "exec")
    except Exception as exc:
        fail(f"la version préparée ne compile pas : {exc}")

    backup_dir = PROJECT / "cache" / "correctifs"
    backup_dir.mkdir(parents=True, exist_ok=True)
    stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    backup = backup_dir / f"mockup_view_avant_rail_cartes_{stamp}.py"

    temporary = TARGET.with_suffix(".rail_cartes.tmp")
    try:
        temporary.write_text(candidate, encoding="utf-8")
        py_compile.compile(str(temporary), doraise=True)
        shutil.copy2(TARGET, backup)
        temporary.replace(TARGET)
        py_compile.compile(str(TARGET), doraise=True)
    except Exception as exc:
        try:
            temporary.unlink(missing_ok=True)
        except Exception:
            pass
        if backup.exists():
            shutil.copy2(backup, TARGET)
        fail(f"installation annulée automatiquement : {exc}")

    print("MAQUETTAGE_RAIL_CARTES_OK")
    print("Fichier modifié : src/gui/views/mockup_view.py")
    print(f"Sauvegarde : {backup}")
    print("Ruban : outils de gestion placés dans le flux après les groupes.")
    print("Pré-chemin de fer : cartes compactes, blancs auto en sous-cartes, compteurs Fait/Reste.")
    print("Ferme complètement PageMaître puis relance-le.")


if __name__ == "__main__":
    main()
